package httpapi
import("context";"encoding/json";"net/http";"net/http/httptest";"os";"path/filepath";"strings";"testing";"time";"github.com/menerjangbadai/dashboard/internal/application";"github.com/menerjangbadai/dashboard/internal/domain")
type authMemory struct{application.AuthStore;revoked bool;flows map[string]application.LoginRequest}
func(a *authMemory) Session(ctx context.Context,hash string)(application.Session,error){if a.revoked||hash!=application.Hash("opaque-test-session"){return application.Session{},domain.ErrUnauthorized};return application.Session{Actor:domain.Actor{UserID:"user",OrgID:"org",Role:"owner"},User:domain.User{ID:"user",DisplayName:"Human",Role:"owner"}},nil}
func(a *authMemory) RevokeSession(context.Context,string)error{a.revoked=true;return nil}
func(a *authMemory) SaveLogin(_ context.Context,f application.LoginRequest)error{if a.flows==nil{a.flows=map[string]application.LoginRequest{}};a.flows[f.StateHash]=f;return nil}
func(a *authMemory) ConsumeLogin(_ context.Context,state,binding string)(application.LoginRequest,error){f,ok:=a.flows[state];if !ok||f.BindingHash!=binding||f.ExpiresAt.Before(time.Now()){return f,domain.ErrUnauthorized};delete(a.flows,state);return f,nil}
type provider struct{application.IdentityProvider}
func(provider) AuthorizationURL(state,nonce,verifier string)string{return "https://idp.test/authorize?state="+state}
func(provider) Health(context.Context)error{return nil}
func setup(t *testing.T)(http.Handler,*authMemory){t.Helper();a:=&authMemory{};return New(Config{PublicURL:"https://app.test",CommitSHA:strings.Repeat("a",40)},application.Brands{},a,provider{},func(context.Context)error{return nil}),a}
func call(h http.Handler,method,path,body,origin,csrf string,cookie bool)*httptest.ResponseRecorder{r:=httptest.NewRequest(method,"https://app.test"+path,strings.NewReader(body));r.Header.Set("Content-Type","application/json");if origin!=""{r.Header.Set("Origin",origin)};if csrf!=""{r.Header.Set("X-CSRF-Token",csrf)};if cookie{r.AddCookie(&http.Cookie{Name:sessionCookie,Value:"opaque-test-session"})};w:=httptest.NewRecorder();h.ServeHTTP(w,r);return w}
func TestSessionAndCSRFLogout(t *testing.T){h,a:=setup(t);w:=call(h,"GET","/api/session","","","",false);if w.Code!=401||!strings.Contains(w.Body.String(),"unauthorized"){t.Fatal(w.Code,w.Body)};w=call(h,"GET","/api/session","","","",true);if w.Code!=200{t.Fatal(w.Code,w.Body)};var v struct{User domain.User `json:"user"`;CSRF string `json:"csrf_token"`};if e:=json.Unmarshal(w.Body.Bytes(),&v);e!=nil||v.User.DisplayName!="Human"||v.CSRF==""{t.Fatal(v,e)}
 for _,tc:=range []struct{origin,csrf string}{{"https://evil.test",v.CSRF},{"",v.CSRF},{"https://app.test",""},{"https://app.test","wrong"}}{w=call(h,"POST","/auth/logout","",tc.origin,tc.csrf,true);if w.Code!=403||a.revoked{t.Fatal(w.Code,"CSRF accepted")}}
 w=call(h,"POST","/auth/logout","","https://app.test",v.CSRF,true);if w.Code!=204||!a.revoked{t.Fatal(w.Code,w.Body)};if call(h,"GET","/api/session","","","",true).Code!=401{t.Fatal("revoked session valid")}
}
func TestHealthAndNoHTMLFallbackOnAPIErrors(t *testing.T){h,_:=setup(t);for _,path:=range []string{"/api/nope","/auth/nope","/api","/auth"}{w:=call(h,"GET",path,"","","",false);if w.Code!=404||!strings.Contains(w.Header().Get("Content-Type"),"application/json"){t.Fatal(path,w.Code,w.Body)}};w:=call(h,"GET","/api/readyz","","","",false);if w.Code!=200||!strings.Contains(w.Body.String(),strings.Repeat("a",40))||!strings.Contains(w.Body.String(),"oidc"){t.Fatal(w.Code,w.Body)};if w.Header().Get("X-Request-ID")==""||w.Header().Get("X-Content-Type-Options")!="nosniff"{t.Fatal(w.Header())}}
func TestLoginStateBrowserBindingAndBadCallback(t *testing.T){h,a:=setup(t);w:=call(h,"GET","/auth/login","","","",false);if w.Code!=302||len(a.flows)!=1{t.Fatal(w.Code,w.Body)};var flow application.LoginRequest;for _,f:=range a.flows{flow=f};if flow.Verifier==""||flow.Nonce==""||flow.ExpiresAt.Sub(time.Now())>6*time.Minute{t.Fatal("unsafe login flow")};cs:=w.Result().Cookies();if len(cs)!=1||!cs[0].Secure||!cs[0].HttpOnly||cs[0].SameSite!=http.SameSiteLaxMode||cs[0].Path!="/"{t.Fatal(cs)};w=call(h,"GET","/auth/callback?state=wrong&code=wrong","","","",false);if w.Code!=401{t.Fatal(w.Code,w.Body)}}
func TestStaticOnlyServesUIAndAssets(t *testing.T){d:=t.TempDir();os.WriteFile(filepath.Join(d,"index.html"),[]byte("<html>UI</html>"),0600);os.WriteFile(filepath.Join(d,"secret.txt"),[]byte("not-public"),0600);h:=New(Config{PublicURL:"https://app.test",CommitSHA:strings.Repeat("a",40),WebDir:d},application.Brands{},&authMemory{},provider{},func(context.Context)error{return nil});for _,p:=range []string{"/","/brands/new"}{w:=call(h,"GET",p,"","","",false);if w.Code!=200||!strings.Contains(w.Body.String(),"UI"){t.Fatal(w.Code,w.Body)}};if w:=call(h,"GET","/secret.txt","","","",false);strings.Contains(w.Body.String(),"not-public"){t.Fatal("arbitrary file leak")}}
